SELECT  FROM dispatch_recovery_checkpoint
WHERE gc_pending = 0 AND tenant_id = #{tenantId} AND dispatch_id = #{dispatchId}
  AND checkpoint_seq = #{checkpointSeq}
LIMIT 1

SELECT  FROM dispatch_recovery_checkpoint
WHERE gc_pending = 0 AND tenant_id = #{tenantId} AND dispatch_id = #{dispatchId}
ORDER BY checkpoint_seq DESC, id DESC
LIMIT #{limit}

SELECT  FROM dispatch_recovery_checkpoint c
WHERE c.gc_pending=0 AND c.tenant_id = #{tenantId} AND c.dispatch_id = #{dispatchId}
  AND ( OR c.id NOT IN (SELECT id FROM (
    SELECT id FROM dispatch_recovery_checkpoint
    WHERE gc_pending=0 AND tenant_id = #{tenantId} AND dispatch_id = #{dispatchId}
    ORDER BY checkpoint_seq DESC, id DESC LIMIT #{retain}
  ) latest_recovery))
  AND 
ORDER BY c.checkpoint_seq DESC, c.id DESC

SELECT COUNT(*) FROM dispatch_result_decision
WHERE tenant_id=#{tenantId} AND dispatch_id=#{dispatchId} AND executor_id <=> #{executorId}
  AND reason_code='PAUSE_CONFIRMED'

mapper.update:
UPDATE dispatch_recovery_checkpoint SET completion_result_id=#{resultId}
WHERE tenant_id=#{tenantId} AND dispatch_id=#{dispatchId} AND checkpoint_seq=#{checkpointSeq}
  AND gc_pending=0 AND (completion_result_id IS NULL OR completion_result_id=#{resultId})
